/**
 * Everything needed to verify an unsigned RGB send before signing it.
 */
data class RgbSendRequest (
    var `network`: Network
    , 
    var `accounts`: WalletAccounts
    , 
    /**
     * Unsigned PSBT exactly as prepared by the gateway, canonical base64.
     */
    var `psbtBase64`: kotlin.String
    , 
    /**
     * Strict-encoded fascia from rgb-lib's `send_begin` (`details.fascia_path`).
     */
    var `fascia`: kotlin.ByteArray
    , 
    /**
     * MPC tree entropy from rgb-lib's `send_begin` (`details.entropy`).
     */
    var `mpcEntropy`: kotlin.ULong
    , 
    /**
     * The RGB invoice the user is paying, exactly as the user supplied it.
     */
    var `invoice`: kotlin.String
    , 
    /**
     * Asset the user approved sending (`rgb:…` contract id).
     */
    var `assetId`: kotlin.String
    , 
    /**
     * Amount of `asset_id` the user approved sending.
     */
    var `amount`: kotlin.ULong
    , 
    /**
     * One proof per existing-UTXO seal in the fascia; empty when there are none.
     */
    var `existingOutputProofs`: List<ExistingOutputProof>
    , 
    /**
     * Highest derivation index accepted for a wallet-owned output.
     */
    var `maxDerivationIndex`: kotlin.UInt
    
){
    

    

    
    companion object
}

