/**
 * Stable failure categories crossing the native-language boundary.
 *
 * Every variant means "do not sign". Messages are deliberately safe to
 * surface: they name output indexes, counts and asset ids only, and never
 * include keys, PSBTs, fascia bytes, invoices or other caller-supplied values.
 */
sealed class VerifierException: kotlin.Exception() {
    
    class InvalidArgument(
        
        val `reason`: kotlin.String
        ) : VerifierException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class InvalidPsbt(
        
        val `reason`: kotlin.String
        ) : VerifierException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class InvalidFascia(
        
        val `reason`: kotlin.String
        ) : VerifierException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class InvalidRgbInvoice(
        
        val `reason`: kotlin.String
        ) : VerifierException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class Rejected(
        
        val `reason`: kotlin.String
        ) : VerifierException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<VerifierException> {
        override fun lift(error_buf: RustBuffer.ByValue): VerifierException = FfiConverterTypeVerifierError.lift(error_buf)
    }

    
}

